void MOD_mkNoc::dump_VCD(tVCDDumpType dt, unsigned int levels, MOD_mkNoc &backing)
{
  vcd_defs(dt, backing);
  if (levels != 1u)
    vcd_submodules(dt, levels - 1u, backing);
}

